{

    internal InnerS3AccessPointAttachmentOntapUnixFileSystemUserFactory UnixUserFactory { get; set; }

    internal InnerS3AccessPointAttachmentOntapWindowsFileSystemUserFactory WindowsUserFactory { get; set; }

    protected override Humidifier.FSx.S3AccessPointAttachmentTypes.OntapFileSystemIdentity Create()
    {
        var ontapFileSystemIdentityResult = CreateOntapFileSystemIdentity();
        factoryAction?.Invoke(ontapFileSystemIdentityResult);

        return ontapFileSystemIdentityResult;
    }

    private Humidifier.FSx.S3AccessPointAttachmentTypes.OntapFileSystemIdentity CreateOntapFileSystemIdentity()
    {
        var ontapFileSystemIdentityResult = new Humidifier.FSx.S3AccessPointAttachmentTypes.OntapFileSystemIdentity();

        return ontapFileSystemIdentityResult;
    }
    public override void CreateChildren(Humidifier.FSx.S3AccessPointAttachmentTypes.OntapFileSystemIdentity result)
    {
        base.CreateChildren(result);

        result.UnixUser ??= UnixUserFactory?.Build();
        result.WindowsUser ??= WindowsUserFactory?.Build();
    }

} // End Of Class

